class Box<T> {
    private T value;

    public void setValue(T value) {
        this.value = value;
    }

    public T getValue() {
        return value;
    }
}

Box<String> box = new Box<>();
box.setValue("Java");
System.out.println(box.getValue());

public class Demo {
    public static <T> void print(T value) {
        System.out.println(value);
    }

    public static void main(String[] args) {
        print("Hello");
        print(100);
        print(12.5);
    }
}

